const formulaire = document.querySelector("#inscription");
const email = formulaire.querySelector("#email");
const motDePasse = formulaire.querySelector("#motdepasse");

const ERREUR_EMAIL = "Adresse email invalide.";
const ERREUR_MDP = "8 caractères minimum, avec une majuscule et un chiffre.";

function montrerErreur(champ, message) {
  champ.setAttribute("aria-invalid", "true");
  champ.closest("div").querySelector(".erreur").textContent = message;
}

function effacerErreur(champ) {
  champ.removeAttribute("aria-invalid");
  champ.closest("div").querySelector(".erreur").textContent = "";
}

function emailValide(valeur) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(valeur);
}

function motDePasseValide(valeur) {
  return valeur.length >= 8 && /[A-Z]/.test(valeur) && /\d/.test(valeur);
}

formulaire.addEventListener("submit", (event) => {
  let valide = true;
  if (!emailValide(email.value)) { montrerErreur(email, ERREUR_EMAIL); valide = false; }
  else effacerErreur(email);
  if (!motDePasseValide(motDePasse.value)) { montrerErreur(motDePasse, ERREUR_MDP); valide = false; }
  else effacerErreur(motDePasse);
  if (!valide) event.preventDefault();
});

async function chargerArticles() {
  const liste = document.querySelector("#articles");
  const statut = document.querySelector("#statut");
  statut.textContent = "Chargement...";
  try {
    const reponse = await fetch("/api/articles");
    if (!reponse.ok) throw new Error(`HTTP ${reponse.status}`);
    const articles = await reponse.json();
    statut.textContent = "";
    liste.innerHTML = articles
      .map((a) => `<li><h3>${a.titre}</h3><p>${a.extrait}</p></li>`)
      .join("");
  } catch (erreur) {
    statut.textContent = "Impossible de charger les articles. Réessayez.";
    console.error("Erreur de chargement :", erreur);
  }
}

document.addEventListener("DOMContentLoaded", chargerArticles);

const CLE = "todo-gen3";
let taches = JSON.parse(localStorage.getItem(CLE) ?? "[]");

function sauver() {
  localStorage.setItem(CLE, JSON.stringify(taches));
}

function rendre() {
  const liste = document.querySelector("#taches");
  liste.innerHTML = "";
  taches.forEach((tache, index) => {
    const li = document.createElement("li");
    const caseACocher = document.createElement("input");
    caseACocher.type = "checkbox";
    caseACocher.checked = tache.fait;
    caseACocher.addEventListener("change", () => {
      taches[index].fait = caseACocher.checked;
      sauver();
    });
    const texte = document.createElement("span");
    texte.textContent = tache.titre;
    if (tache.fait) texte.style.textDecoration = "line-through";
    const bouton = document.createElement("button");
    bouton.textContent = "Supprimer";
    bouton.setAttribute("aria-label", `Supprimer : ${tache.titre}`);
    bouton.addEventListener("click", () => {
      taches.splice(index, 1);
      sauver();
      rendre();
    });
    li.append(caseACocher, texte, bouton);
    liste.append(li);
  });
}

