import { ButtonHTMLAttributes } from "react";

type Variante = "primary" | "secondary" | "danger";
type Taille = "sm" | "md" | "lg";

interface BoutonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variante?: Variante;
  taille?: Taille;
}

const STYLES_VARIANTE: Record<Variante, string> = {
  primary: "bg-green-700 text-white hover:bg-green-800",
  secondary: "bg-gray-200 text-gray-900 hover:bg-gray-300",
  danger: "bg-red-600 text-white hover:bg-red-700",
};

const STYLES_TAILLE: Record<Taille, string> = {
  sm: "px-3 py-1.5 text-sm",
  md: "px-4 py-2 text-base",
  lg: "px-6 py-3 text-lg",
};

export function Bouton({
  variante = "primary",
  taille = "md",
  disabled,
  className = "",
  ...props
}: BoutonProps) {
  return (
    <button
      disabled={disabled}
      className={`rounded-lg font-semibold transition ${STYLES_VARIANTE[variante]} ${STYLES_TAILLE[taille]} ${disabled ? "opacity-50 cursor-not-allowed" : ""} ${className}`}
      {...props}
    />
  );
}

